<script lang="ts">
 import { untrack } from 'svelte';
 import { invalidateAll } from '$app/navigation';
 import { api,passkey } from '#lib/client';
 import type { Folder,Item } from '#lib/types';
 import Scrapbook from '#lib/components/Scrapbook.svelte';
 import ItemEditor from '#lib/components/ItemEditor.svelte';
 import Modal from '#lib/components/Modal.svelte';
 import Profile from '#lib/components/Profile.svelte';
 import Connections from '#lib/components/Connections.svelte';
 let {data}=$props();
 let folders=$state<Folder[]>(untrack(()=>data.folders)),items=$state<Item[]>(untrack(()=>data.items)),hasMore=$state(untrack(()=>data.hasMore));
 let view=$state('all'),navOpen=$state(false),query=$state(''),message=$state(''),busy=$state(false);
 let editor=$state(false),editing=$state<Item|null>(null),folderDialog=$state(false),folderName=$state(''),renaming=$state(false),shareDialog=$state(false),shareUrl=$state(''),trash=$state<Item[]>([]);
 let signup=$state(true),email=$state(''),password=$state(''),name=$state(''),authMessage=$state('');
 const current=$derived(folders.find(f=>f.id===view));
 const visible=$derived(items.filter(i=>(view==='all'||i.folder_id===view)&&(!query||i.title.toLowerCase().includes(query.toLowerCase()))));
 const title=$derived(current?.name||'All the things');
 let loadVersion=0;let searchTimer:ReturnType<typeof setTimeout>;
 function statePath(offset=0){return 'state?'+new URLSearchParams({offset:String(offset),...(current?{folder:current.id}:{}),q:query});}
 async function refresh(){const version=++loadVersion;const next=await api(statePath());if(version!==loadVersion)return;folders=next.folders;items=next.items;hasMore=next.hasMore;await invalidateAll();}
 function search(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>refresh().catch(e=>message=e.message),250);}
 async function more(){try{const next=await api(statePath(items.length));items=[...items,...next.items];hasMore=next.hasMore;}catch(e){message=(e as Error).message;}}
 async function auth(e:SubmitEvent){e.preventDefault();busy=true;authMessage='';try{await api('auth/'+(signup?'register':'login'),'POST',signup?{email,password,name}:{email,password});await refresh();}catch(e){authMessage=(e as Error).message;}finally{busy=false;}}
 async function usePasskey(){busy=true;authMessage='';try{if(signup&&(!email||!name)){authMessage='Enter your name and email first, then create your passkey.';return;}await passkey(signup?'register':'login',signup?{email,name}:undefined);await refresh();}catch(e){authMessage=(e as Error).name==='NotAllowedError'?'Passkey request cancelled. You can try again.':(e as Error).message;}finally{busy=false;}}
 async function signout(){await api('auth/logout','POST',{});location.href='/';}
 function navigate(next:string){view=next;query='';navOpen=false;message='';if(next!=='trash'&&next!=='profile'&&next!=='connections')refresh().catch(e=>message=e.message);if(next==='trash')api('trash').then(v=>trash=v).catch(e=>message=e.message);}
 async function saveFolder(e:SubmitEvent){e.preventDefault();busy=true;message='';try{const f=await api('folders'+(renaming?'/'+view:''),renaming?'PATCH':'POST',{name:folderName});await refresh();view=f.id;folderDialog=false;}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function remove(item:Item){try{await api('items/'+item.id+'?revision='+item.revision,'DELETE');await refresh();message='Moved to trash. You can restore it from the sidebar.';}catch(e){message=(e as Error).message;}}
 async function restore(item:Item){try{await api('items/'+item.id+'/restore','POST',{});trash=await api('trash');await refresh();message='Item restored.';}catch(e){message=(e as Error).message;}}
 async function share(){busy=true;message='';try{shareUrl=(await api('folders/'+view+'/share','POST',{})).url;await refresh();}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function revoke(){busy=true;try{await api('folders/'+view+'/share','DELETE');shareUrl='';await refresh();message='Folder is private. The old link no longer works.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function copy(){try{await navigator.clipboard.writeText(shareUrl);message='Link copied.';}catch{message='Select and copy the link below.';}}
</script>
<svelte:head><title>{data.user?title+' — Wishlist':'Wishlist — A place for your someday things'}</title><meta name="description" content="A personal scrapbook for things worth saving. Collect your finds, share a folder, and let your AI keep the details."/></svelte:head>
{#if !data.user}
 <div class="welcome">
 <header class="welcome-header"><a class="wordmark" href="/">Wishlist<span class="wordmark-dot">.</span></a><span class="edition">A personal collection of possibilities</span><a class="text-button" href="/demo">Take a look inside</a></header>
 <main class="welcome-main"><section class="welcome-story"><span class="eyebrow">For your someday, and your everyday</span><h1>Some things<br/>stay with you.</h1><p>A quiet place for the things that catch your eye.<br class="desktop-only"/> Save them, collect them, come back to them.</p><div class="welcome-still-life"><div class="preview-stamp"><img src="/samples/mug.svg" alt="Illustration of a ceramic mug"/><span>The slow morning mug</span><span class="preview-price">€38</span></div><div class="preview-object"><img src="/samples/lamp.svg" alt="Illustration of a table lamp"/><span>A little more light</span></div><span class="still-life-note">a few things for a slower day</span></div></section>
 <section class="auth-paper"><span class="eyebrow">Your own little corner</span><h2>{signup?'Start collecting.':'Welcome back.'}</h2><p class="subtle">{signup?'Make room for a little possibility.':'Your finds are right where you left them.'}</p><form class="stacked-form" onsubmit={auth}>{#if signup}<label>Your name<input bind:value={name} autocomplete="name" required maxlength="100"/></label>{/if}<label>Email address<input type="email" bind:value={email} autocomplete="email" required maxlength="254"/></label><label>Password<input type="password" bind:value={password} autocomplete={signup?'new-password':'current-password'} minlength={signup?12:undefined} maxlength="256" required/></label>{#if signup}<p class="field-hint">At least 12 characters, or use a passkey below.</p>{/if}<button class="button primary" disabled={busy}>{busy?'One moment…':signup?'Create your account':'Sign in'}</button></form><div class="or-rule"><span>or</span></div><button class="button full-width" disabled={busy} onclick={usePasskey}>{signup?'Create account with a passkey':'Sign in with a passkey'}</button><p class="auth-switch">{signup?'Already have a collection?':'New here?'} <button class="inline-link" onclick={()=>{signup=!signup;authMessage='';}}>{signup?'Sign in':'Create an account'}</button></p>{#if authMessage}<p class="form-error" role="alert">{authMessage}</p>{/if}</section></main>
 <footer class="welcome-footer"><span>Collected with intention.</span><span>Your finds. Your space.</span></footer></div>
{:else}
 <div class="app-shell">
 <aside class:nav-open={navOpen} class="sidebar"><a href="/" class="wordmark">Wishlist<span class="wordmark-dot">.</span></a><p class="sidebar-caption">A few things to look forward to.</p><nav aria-label="Your collections"><button class:active={view==='all'} onclick={()=>navigate('all')}>All the things <span>{folders.reduce((n,f)=>n+f.count,0)}</span></button><p class="nav-label">Your folders</p>{#each folders as f}<button class:active={view===f.id} onclick={()=>navigate(f.id)}>{f.name}<span>{f.count}</span></button>{/each}<button class="new-folder" onclick={()=>{renaming=false;folderName='';folderDialog=true;navOpen=false;}}>New folder</button></nav><div class="sidebar-bottom"><button class:active={view==='connections'} onclick={()=>navigate('connections')}>Connect AI</button><button class:active={view==='trash'} onclick={()=>navigate('trash')}>Trash</button><button class:active={view==='profile'} onclick={()=>navigate('profile')}>{data.user.name}<small>Your profile</small></button><button class="signout" onclick={signout}>Sign out</button></div></aside>
 <div class="main-column"><div class="mobile-bar"><a href="/" class="wordmark">Wishlist.</a><button class="text-button" onclick={()=>navOpen=!navOpen} aria-expanded={navOpen}>Folders</button></div>
 <main class="collection-main">
 {#if view==='profile'}<Profile user={data.user} onupdated={()=>invalidateAll()}/>{:else if view==='connections'}<Connections {folders}/>{:else if view==='trash'}<div class="settings-page"><span class="eyebrow">Nothing lost</span><h1>A second thought.</h1><p class="intro">Your removed items stay here until you want them back.</p>{#each trash as item}<div class="settings-row"><strong>{item.title}</strong><button class="text-button" onclick={()=>restore(item)}>Restore</button></div>{:else}<p class="subtle">The trash is empty.</p>{/each}</div>{:else}
 <header class="collection-heading"><div><span class="eyebrow">Your personal collection</span><h1>{title}<span class="heading-period">.</span></h1><p>{current?'A little collection, with a little intention.':'For the someday, the everyday, and everything in between.'}</p></div><div class="header-actions">{#if current}<button class="text-button" onclick={()=>{shareDialog=true;shareUrl='';message='';}}>Share folder</button>{/if}<button class="button primary" onclick={()=>{editor=true;editing=null;}}>Add a find</button></div></header>
 <div class="collection-toolbar"><span>{visible.length}{hasMore?'+':''} {visible.length===1?'thing':'things'} worth remembering{#if current}<span class="toolbar-dot">·</span>{current.shared?'Shared by link':'Just for you'}{/if}</span><div>{#if current}<button class="text-button" onclick={()=>{renaming=true;folderName=current.name;folderDialog=true;}}>Rename folder</button>{/if}<input type="search" aria-label="Search saved items" bind:value={query} oninput={search} placeholder="Find something…"/></div></div>
 <Scrapbook items={visible} folderName={title} {hasMore} onmore={more} onedit={item=>{editing=item;editor=true;}} ondelete={remove}/>
 <footer class="collection-footer"><span>A collection, never quite complete.</span><span>One good find at a time.</span></footer>
 {/if}
 {#if message&&!shareDialog&&!folderDialog}<div class="notice" role="status">{message}<button class="text-button" onclick={()=>message=''}>Dismiss</button></div>{/if}
 </main></div></div>
 {#if editor}<ItemEditor item={editing} {folders} folderId={current?.id||folders[0]?.id||''} currency={data.user.currency} onclose={()=>editor=false} onsaved={()=>{editor=false;refresh().catch(e=>message=e.message);}}/>{/if}
 {#if folderDialog}<Modal title={renaming?'Rename folder':'A new folder'} onclose={()=>folderDialog=false}><span class="eyebrow">Give it a home</span><h2>{renaming?'A different name.':'A new little collection.'}</h2><form class="stacked-form" onsubmit={saveFolder}><label>Folder name<input bind:value={folderName} required maxlength="100" placeholder="Things for a slow Sunday"/></label>{#if message}<p role="alert" class="form-error">{message}</p>{/if}<button class="button primary" disabled={busy}>{busy?'Saving…':renaming?'Save name':'Create folder'}</button></form></Modal>{/if}
 {#if shareDialog&&current}<Modal title="Share folder" onclose={()=>shareDialog=false}><span class="eyebrow">A little inspiration, passed along</span><h2>Share {current.name}.</h2><p>Anyone with the link can view this folder, without an account. Your private notes stay private.</p>{#if shareUrl}<label>Your view-only link<input value={shareUrl} readonly/></label><button class="button" onclick={copy}>Copy link</button>{:else}<p class="subtle">{current.shared?'This folder has an active link. Create a replacement if you no longer have it; the old link will stop working.':'This folder is currently private.'}</p>{/if}<div class="detail-actions"><button class="button primary" disabled={busy} onclick={share}>{current.shared?'Replace sharing link':'Create sharing link'}</button>{#if current.shared}<button class="text-button" disabled={busy} onclick={revoke}>Make private</button>{/if}</div>{#if message}<p class="notice" role="status">{message}</p>{/if}</Modal>{/if}
{/if}
